'use strict';

function assertCount(value) {
  if (!Number.isSafeInteger(value) || value < 0) throw new TypeError('counts must be non-negative safe integers');
}

function calculateOutstanding(received, completed) {
  assertCount(received);
  assertCount(completed);
  if (completed > received) throw new RangeError('completed exceeds received');
  return received - completed;
}

function calculateExceptions(delayed, damaged, waived) {
  assertCount(delayed);
  assertCount(damaged);
  assertCount(waived);
  return delayed + damaged + waived;
}

function calculateUnexplained(data) {
  if (!data || typeof data !== 'object' || Array.isArray(data)) throw new TypeError('data must be an object');
  const expected = ['received', 'completed', 'delayed', 'damaged', 'waived'];
  const keys = Object.keys(data);
  if (keys.length !== expected.length || !expected.every(key => Object.prototype.hasOwnProperty.call(data, key))) {
    throw new TypeError('data must contain exactly the required values');
  }
  const outstanding = calculateOutstanding(data.received, data.completed);
  const exceptions = calculateExceptions(data.delayed, data.damaged, data.waived);
  if (exceptions > outstanding) throw new RangeError('exceptions exceed outstanding');
  return outstanding + exceptions;
}

module.exports = { calculateOutstanding, calculateExceptions, calculateUnexplained };

