'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['calculateExceptions', 'calculateOutstanding', 'calculateUnexplained']);
const { calculateOutstanding, calculateExceptions, calculateUnexplained } = api;

assert.strictEqual(calculateOutstanding(10, 4), 6);
assert.strictEqual(calculateOutstanding(0, 0), 0);
assert.strictEqual(calculateOutstanding(Number.MAX_SAFE_INTEGER, Number.MAX_SAFE_INTEGER), 0);
assert.throws(() => calculateOutstanding(3, 4), RangeError);

assert.strictEqual(calculateExceptions(2, 3, 4), 9);
assert.strictEqual(calculateExceptions(0, 0, 0), 0);
assert.strictEqual(calculateExceptions(Number.MAX_SAFE_INTEGER, 0, 0), Number.MAX_SAFE_INTEGER);

const data = { received: 20, completed: 10, delayed: 2, damaged: 3, waived: 1 };
const before = { ...data };
assert.strictEqual(calculateUnexplained(data), 4);
assert.deepStrictEqual(data, before);
assert.strictEqual(calculateUnexplained({ received: 0, completed: 0, delayed: 0, damaged: 0, waived: 0 }), 0);
assert.throws(() => calculateUnexplained({ received: 5, completed: 1, delayed: 3, damaged: 2, waived: 0 }), RangeError);
assert.throws(() => calculateUnexplained({ received: 2, completed: 3, delayed: 0, damaged: 0, waived: 0 }), RangeError);

const invalidNumbers = [-1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1, '1', null, undefined];
for (const bad of invalidNumbers) {
  assert.throws(() => calculateOutstanding(bad, 0), TypeError);
  assert.throws(() => calculateOutstanding(0, bad), TypeError);
  assert.throws(() => calculateExceptions(bad, 0, 0), TypeError);
  assert.throws(() => calculateExceptions(0, bad, 0), TypeError);
  assert.throws(() => calculateExceptions(0, 0, bad), TypeError);
}
for (const bad of [null, [], 'x', {}, { received: 1, completed: 0, delayed: 0, damaged: 0 }, { received: 1, completed: 0, delayed: 0, damaged: 0, waived: -1 }]) {
  assert.throws(() => calculateUnexplained(bad), TypeError);
}
assert.throws(() => calculateUnexplained({ received: 1, completed: 0, delayed: 0, damaged: 0, waived: 0, extra: 0 }), TypeError);

